PRAGMA foreign_keys = ON;

CREATE TABLE owners (owner_id TEXT PRIMARY KEY, deletion_epoch INTEGER NOT NULL DEFAULT 0 CHECK(deletion_epoch>=0), created_at TEXT NOT NULL);
CREATE TABLE worlds (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(owner_id) REFERENCES owners(owner_id));
CREATE INDEX worlds_owner ON worlds(owner_id,created_at);
CREATE TABLE stories (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, world_id TEXT NOT NULL REFERENCES worlds(id), name TEXT NOT NULL, character_ids_json TEXT NOT NULL DEFAULT '[]', worldbook_ids_json TEXT NOT NULL DEFAULT '[]', player_character_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX stories_owner ON stories(owner_id,world_id,created_at);
CREATE TABLE branches (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, story_id TEXT NOT NULL REFERENCES stories(id), name TEXT NOT NULL, parent_branch_id TEXT REFERENCES branches(id), fork_seq INTEGER NOT NULL DEFAULT 0, head_seq INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 0, projection_revision INTEGER NOT NULL DEFAULT 0, scene_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, CHECK(head_seq>=fork_seq));
CREATE INDEX branches_story ON branches(owner_id,story_id);
CREATE TABLE branch_lineage (branch_id TEXT NOT NULL REFERENCES branches(id), ancestor_id TEXT NOT NULL REFERENCES branches(id), max_seq INTEGER, max_memory_rowid INTEGER, max_grant_rowid INTEGER, max_binding_rowid INTEGER, max_capability_rowid INTEGER, depth INTEGER NOT NULL, PRIMARY KEY(branch_id,ancestor_id));
CREATE TABLE scene_snapshots(branch_id TEXT NOT NULL REFERENCES branches(id),event_seq INTEGER NOT NULL,scene_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(branch_id,event_seq));
CREATE TABLE resource_bindings(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,branch_id TEXT NOT NULL REFERENCES branches(id),asset_id TEXT NOT NULL,revision INTEGER NOT NULL,kind TEXT NOT NULL,recorded_seq INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX bindings_scope ON resource_bindings(owner_id,branch_id,recorded_seq,asset_id);
CREATE TABLE sessions (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, branch_id TEXT NOT NULL REFERENCES branches(id), name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX sessions_branch ON sessions(owner_id,branch_id,created_at);
CREATE TABLE sources (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, world_id TEXT NOT NULL REFERENCES worlds(id), story_id TEXT REFERENCES stories(id), branch_id TEXT REFERENCES branches(id), event_id TEXT, kind TEXT NOT NULL, asset_id TEXT, version INTEGER NOT NULL DEFAULT 1, generation INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','deleted')), text TEXT, known_by_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, deleted_at TEXT);
CREATE INDEX sources_scope ON sources(owner_id,world_id,story_id,branch_id,status);
CREATE TABLE events (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, story_id TEXT NOT NULL REFERENCES stories(id), branch_id TEXT NOT NULL REFERENCES branches(id), session_id TEXT REFERENCES sessions(id), source_id TEXT NOT NULL UNIQUE REFERENCES sources(id), seq INTEGER NOT NULL, role TEXT NOT NULL, speaker_id TEXT, scene_time REAL NOT NULL, story_time TEXT, known_by_json TEXT NOT NULL DEFAULT '[]', request_id TEXT NOT NULL, ordinal INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(branch_id,seq), UNIQUE(branch_id,request_id,ordinal));
CREATE INDEX events_branch ON events(owner_id,branch_id,seq);
CREATE TABLE turns (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, branch_id TEXT NOT NULL REFERENCES branches(id), session_id TEXT NOT NULL REFERENCES sessions(id), request_id TEXT NOT NULL, first_seq INTEGER NOT NULL, last_seq INTEGER NOT NULL, payload_hash TEXT NOT NULL, owner_epoch INTEGER NOT NULL, task_id TEXT, task_attempt INTEGER, task_cancel_epoch INTEGER, created_at TEXT NOT NULL, UNIQUE(owner_id,branch_id,request_id));
CREATE TABLE source_spans (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), source_version INTEGER NOT NULL, source_generation INTEGER NOT NULL, start_offset INTEGER NOT NULL CHECK(start_offset>=0), end_offset INTEGER NOT NULL CHECK(end_offset>start_offset), quote TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(source_id,source_version,source_generation,start_offset,end_offset));
CREATE INDEX spans_source ON source_spans(source_id);
CREATE TRIGGER spans_exact BEFORE INSERT ON source_spans BEGIN
 SELECT RAISE(ABORT,'SOURCE_FENCE_OR_QUOTE') WHERE NOT EXISTS(SELECT 1 FROM sources s WHERE s.id=NEW.source_id AND s.status='active' AND s.version=NEW.source_version AND s.generation=NEW.source_generation AND substr(s.text,NEW.start_offset+1,NEW.end_offset-NEW.start_offset)=NEW.quote);
END;
CREATE TABLE knowledge_grants (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, branch_id TEXT NOT NULL REFERENCES branches(id), source_id TEXT NOT NULL REFERENCES sources(id), span_id TEXT NOT NULL REFERENCES source_spans(id), character_id TEXT NOT NULL, recorded_seq INTEGER NOT NULL, acquired_seq INTEGER NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('witnessed','told','author','persona','public')), status TEXT NOT NULL CHECK(status IN ('grant','revoke')), created_at TEXT NOT NULL);
CREATE INDEX grants_scope ON knowledge_grants(owner_id,branch_id,source_id,character_id,recorded_seq);
CREATE TABLE memory_versions (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, story_id TEXT NOT NULL REFERENCES stories(id), branch_id TEXT NOT NULL REFERENCES branches(id), memory_key TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('canon','belief','relation','episode','observation','experience','procedure')), subject TEXT NOT NULL, predicate TEXT NOT NULL, value_json TEXT NOT NULL, text TEXT NOT NULL, search_text TEXT NOT NULL, known_by_json TEXT NOT NULL, observer_id TEXT, authority INTEGER NOT NULL DEFAULT 50, confidence REAL NOT NULL DEFAULT 1 CHECK(confidence>=0 AND confidence<=1), valid_from REAL, valid_to REAL, origin_seq INTEGER NOT NULL, recorded_seq INTEGER NOT NULL, recorded_at TEXT NOT NULL, revision INTEGER NOT NULL, supersedes_id TEXT REFERENCES memory_versions(id), status TEXT NOT NULL CHECK(status IN ('active','forgotten','invalidated','draft','suspended','retired')), data_json TEXT NOT NULL DEFAULT '{}', idempotency_key TEXT NOT NULL, UNIQUE(owner_id,branch_id,idempotency_key), CHECK(valid_to IS NULL OR valid_from IS NULL OR valid_to>=valid_from));
CREATE INDEX memories_scope ON memory_versions(owner_id,branch_id,recorded_seq,memory_key);
CREATE INDEX memories_entities ON memory_versions(owner_id,branch_id,subject,predicate);
CREATE TABLE memory_evidence (memory_id TEXT NOT NULL REFERENCES memory_versions(id), span_id TEXT NOT NULL REFERENCES source_spans(id), PRIMARY KEY(memory_id,span_id));
CREATE INDEX evidence_span ON memory_evidence(span_id,memory_id);
CREATE TRIGGER memory_evidence_guard BEFORE INSERT ON memory_evidence BEGIN
 SELECT RAISE(ABORT,'MEMORY_SOURCE_SCOPE') WHERE NOT EXISTS(SELECT 1 FROM memory_versions m JOIN source_spans p ON p.id=NEW.span_id JOIN sources s ON s.id=p.source_id JOIN stories st ON st.id=m.story_id WHERE m.id=NEW.memory_id AND s.owner_id=m.owner_id AND s.world_id=st.world_id AND s.status='active' AND s.version=p.source_version AND s.generation=p.source_generation AND (s.story_id IS NULL OR s.story_id=m.story_id) AND (s.event_id IS NULL OR EXISTS(SELECT 1 FROM events e JOIN branch_lineage l ON l.ancestor_id=e.branch_id AND l.branch_id=m.branch_id WHERE e.id=s.event_id AND (l.max_seq IS NULL OR e.seq<=l.max_seq) AND e.seq<=m.recorded_seq)));
END;
CREATE TABLE memory_heads (branch_id TEXT NOT NULL REFERENCES branches(id), memory_key TEXT NOT NULL, memory_id TEXT NOT NULL REFERENCES memory_versions(id), PRIMARY KEY(branch_id,memory_key));
CREATE VIRTUAL TABLE memory_fts USING fts5(memory_id UNINDEXED, search_text, tokenize='unicode61');
CREATE TRIGGER memory_fts_insert AFTER INSERT ON memory_versions BEGIN INSERT INTO memory_fts(memory_id,search_text) VALUES(NEW.id,NEW.search_text); END;
CREATE TABLE memory_dependencies (memory_id TEXT NOT NULL REFERENCES memory_versions(id), depends_on_id TEXT NOT NULL REFERENCES memory_versions(id), PRIMARY KEY(memory_id,depends_on_id));
CREATE INDEX deps_parent ON memory_dependencies(depends_on_id);
CREATE TABLE memory_cursors (branch_id TEXT NOT NULL REFERENCES branches(id), extractor_version TEXT NOT NULL, applied_seq INTEGER NOT NULL DEFAULT 0, generation INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, PRIMARY KEY(branch_id,extractor_version));
CREATE TABLE memory_event_applications(branch_id TEXT NOT NULL REFERENCES branches(id),event_id TEXT NOT NULL REFERENCES events(id),event_seq INTEGER NOT NULL,extractor_version TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(branch_id,event_id,extractor_version));
CREATE TABLE observation_batches (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, branch_id TEXT NOT NULL REFERENCES branches(id), cursor INTEGER NOT NULL, owner_epoch INTEGER NOT NULL, status TEXT NOT NULL, input_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE procedure_uses (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, branch_id TEXT NOT NULL REFERENCES branches(id), procedure_id TEXT NOT NULL REFERENCES memory_versions(id), revision_id TEXT NOT NULL REFERENCES memory_versions(id), phase TEXT NOT NULL CHECK(phase IN ('retrieved','planned','applied')), outcome TEXT NOT NULL, category TEXT, conditions_json TEXT NOT NULL, evidence_json TEXT NOT NULL, recorded_seq INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE capability_versions(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,branch_id TEXT NOT NULL REFERENCES branches(id),actor_id TEXT NOT NULL,capability TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('available','lost','uncertain')),data_json TEXT NOT NULL,evidence_json TEXT NOT NULL,source_memory_id TEXT NOT NULL REFERENCES memory_versions(id),recorded_seq INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX capabilities_scope ON capability_versions(owner_id,branch_id,actor_id,capability,recorded_seq);
CREATE TABLE deletion_tombstones (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, kind TEXT NOT NULL, target_id TEXT NOT NULL, branch_id TEXT, generation INTEGER NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX tombstone_target ON deletion_tombstones(owner_id,kind,target_id);
CREATE TABLE source_deletion_members(source_id TEXT NOT NULL REFERENCES sources(id),memory_id TEXT NOT NULL REFERENCES memory_versions(id),PRIMARY KEY(source_id,memory_id));
CREATE TABLE write_guards (token TEXT PRIMARY KEY, ok INTEGER NOT NULL CHECK(ok=1));

CREATE TABLE tasks(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,branch_id TEXT,session_id TEXT,command_id TEXT NOT NULL,expected_head INTEGER,status TEXT NOT NULL,attempt INTEGER NOT NULL DEFAULT 1,input_json TEXT NOT NULL,config_json TEXT NOT NULL,context_json TEXT NOT NULL DEFAULT '{}',draft_text TEXT NOT NULL DEFAULT '',error_json TEXT,cancel_epoch INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(owner_id,command_id));
CREATE INDEX tasks_pending ON tasks(owner_id,status,updated_at);
CREATE TABLE outbox(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,branch_id TEXT,kind TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX outbox_pending ON outbox(status,created_at);
CREATE TABLE assets(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,kind TEXT NOT NULL,name TEXT NOT NULL,revision INTEGER NOT NULL,raw_json TEXT NOT NULL,data_json TEXT NOT NULL,png_key TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX assets_owner ON assets(owner_id,kind,updated_at);
CREATE TABLE asset_revisions(id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES assets(id),revision INTEGER NOT NULL,raw_json TEXT NOT NULL,data_json TEXT NOT NULL,png_key TEXT,created_at TEXT NOT NULL,UNIQUE(asset_id,revision));
CREATE TABLE model_settings(owner_id TEXT PRIMARY KEY,data_json TEXT NOT NULL,updated_at TEXT NOT NULL);

CREATE TRIGGER immutable_events BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'IMMUTABLE_EVENT'); END;
CREATE TRIGGER immutable_memories BEFORE UPDATE ON memory_versions WHEN NOT (NEW.id=OLD.id AND NEW.owner_id=OLD.owner_id AND NEW.branch_id=OLD.branch_id AND NEW.text='' AND NEW.search_text='' AND NEW.value_json='null' AND NEW.data_json='{}' AND NEW.subject='' AND NEW.predicate='' AND EXISTS(SELECT 1 FROM source_deletion_members d JOIN deletion_tombstones t ON t.target_id=d.source_id AND t.kind='source' AND t.owner_id=OLD.owner_id WHERE d.memory_id=OLD.id)) BEGIN SELECT RAISE(ABORT,'IMMUTABLE_MEMORY_VERSION'); END;
CREATE TRIGGER immutable_spans BEFORE UPDATE ON source_spans WHEN NOT (NEW.quote='' AND EXISTS(SELECT 1 FROM sources WHERE id=OLD.source_id AND status='deleted')) BEGIN SELECT RAISE(ABORT,'IMMUTABLE_SOURCE_SPAN'); END;
CREATE TRIGGER task_turn_fence BEFORE INSERT ON turns BEGIN
 SELECT RAISE(ABORT,'OWNER_DELETION_FENCE') WHERE NOT EXISTS(SELECT 1 FROM owners WHERE owner_id=NEW.owner_id AND deletion_epoch=NEW.owner_epoch);
 SELECT RAISE(ABORT,'TASK_COMMIT_FENCE') WHERE NEW.task_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tasks t WHERE t.id=NEW.task_id AND t.owner_id=NEW.owner_id AND t.branch_id=NEW.branch_id AND t.session_id=NEW.session_id AND t.attempt=NEW.task_attempt AND t.cancel_epoch=NEW.task_cancel_epoch AND t.status IN ('running','validating','committing'));
END;
